    const date = new Date(2021, 2, 25);
    const result = clamp(date, interval);
    expect(result).toEqual(date);
  });

  it("returns the later endpoint for a date after the interval", () => {
    const result = clamp(new Date(2021, 3, 2), interval);
    expect(result).toEqual(interval.start);
  });
});

