import { TZDate, tz } from "@date-fns/tz";
import { UTCDate } from "@date-fns/utc";
import { describe, expect, it } from "vitest";
import { assertType } from "../_lib/test/index.js";
import { clamp } from "./index.js";

describe("clamp", () => {
  it("accepts timestamps", () => {
    const start = new Date(2000, 1, 1).getTime();
    const date = new Date(2000, 1, 2).getTime();
    const end = new Date(2000, 1, 3).getTime();
    const result = clamp(date, { start, end });
    expect(result).toEqual(new Date(2000, 1, 2));
  });

  it("returns the start date when the date is less than start", () => {
    const start = new Date(2001, 1, 1);
    const date = new Date(2000, 1, 1);
    const end = new Date(2020, 1, 1);
    const result = clamp(date, { start, end });
    expect(result).toEqual(new Date(2001, 1, 1));
  });

  it("returns the end date when the date is greater than the end date", () => {
    const start = new Date(2000, 1, 1);
    const date = new Date(2003, 1, 1);
    const end = new Date(2001, 1, 1);
    const result = clamp(date, { start, end });
    expect(result).toEqual(new Date(2001, 1, 1));
  });

  it("returns the date when the date is within the bound of start and end", () => {
    const start = new Date(2000, 1, 1);
    const date = new Date(2001, 1, 1);
    const end = new Date(2003, 1, 1);
    const result = clamp(date, { start, end });
    expect(result).toEqual(new Date(2001, 1, 1));
  });

  it("resolves the date type by default", () => {
    const result = clamp(Date.now(), {
      start: Date.now() - 1000,
      end: Date.now() + 1000,
    });
    expect(result).toBeInstanceOf(Date);
    assertType<assertType.Equal<Date, typeof result>>(true);
  });

  it("resolves the argument type if a date extension is passed", () => {
    const result = clamp(new UTCDate(), {
      start: Date.now(),
      end: Date.now(),
    });
    expect(result).toBeInstanceOf(UTCDate);
    assertType<assertType.Equal<UTCDate, typeof result>>(true);
  });

  it("resolves the first argument date object type", () => {
    const argResult = clamp(new UTCDate(), {
      start: new TZDate(),
      end: new UTCDate(),
    });
    expect(argResult).toBeInstanceOf(UTCDate);
    assertType<assertType.Equal<UTCDate, typeof argResult>>(true);

    const startResult = clamp(Date.now(), {
      start: new TZDate(),
      end: new UTCDate(),
    });
    expect(startResult).toBeInstanceOf(TZDate);
    assertType<assertType.Equal<TZDate, typeof startResult>>(true);

    const endResult = clamp(Date.now(), {
      start: Date.now(),
      end: new UTCDate(),
    });
    expect(endResult).toBeInstanceOf(UTCDate);
    assertType<assertType.Equal<UTCDate, typeof endResult>>(true);
  });

  describe("context", () => {
    it("allows to specify the context", () => {
      const interval = {
        start: "2024-04-10T07:00:00Z",
        end: "2024-04-12T07:00:00Z",
      };
      expect(
        clamp("2024-04-11T07:00:00Z", interval, {
          in: tz("America/Los_Angeles"),
        }).toISOString(),
      ).toBe("2024-04-11T00:00:00.000-07:00");
      expect(
        clamp("2024-04-11T07:00:00Z", interval, {
          in: tz("Asia/Singapore"),
        }).toISOString(),
      ).toBe("2024-04-11T15:00:00.000+08:00");
    });

    it("resolves the context date type", () => {
      const interval = {
        start: new Date("2014-09-01T00:00:00Z"),
        end: new Date("2014-09-05T00:00:00Z"),
      };
      const result = clamp(interval.start, interval, {
        in: tz("Asia/Tokyo"),
      });
      expect(result).toBeInstanceOf(TZDate);
      assertType<assertType.Equal<TZDate, typeof result>>(true);
    });
  });
});

import { tz } from "@date-fns/tz";
import { describe, expect, it } from "vitest";
import type { ContextOptions, DateArg, Interval } from "../types.js";
import { isWithinInterval } from "./index.js";

describe("isWithinInterval", () => {
  it("returns true if the given date in within the given interval", () => {
    const result = isWithinInterval(new Date(2014, 9 /* Oct */, 31), {
      start: new Date(2014, 8 /* Sep */, 1),
      end: new Date(2014, 11 /* Dec */, 31),
    });
    expect(result).toBe(true);
  });

  it("returns true if the given date has same time as the left boundary of the interval", () => {
    const result = isWithinInterval(new Date(2014, 8 /* Sep */, 1), {
      start: new Date(2014, 8 /* Sep */, 1),
      end: new Date(2014, 11 /* Dec */, 31),
    });
    expect(result).toBe(true);
  });

  it("returns true if the given date has same time as the right boundary of the interval", () => {
    const result = isWithinInterval(new Date(2014, 11 /* Dec */, 31), {
      start: new Date(2014, 8 /* Sep */, 1),
      end: new Date(2014, 11 /* Dec */, 31),
    });
    expect(result).toBe(true);
  });

  it("returns true if the given date and the both boundaries are the same", () => {
    const result = isWithinInterval(new Date(2014, 11 /* Dec */, 31), {
      start: new Date(2014, 11 /* Dec */, 31),
      end: new Date(2014, 11 /* Dec */, 31),
    });
    expect(result).toBe(true);
  });

  it("returns false if the given date is outside of the interval", () => {
    const result = isWithinInterval(new Date(2014, 1 /* Feb */, 11), {
      start: new Date(2014, 8 /* Sep */, 1),
      end: new Date(2014, 11 /* Dec */, 31),
    });
    expect(result).toBe(false);
  });

  it("accepts a timestamp", () => {
    const result = isWithinInterval(new Date(2014, 9 /* Oct */, 31).getTime(), {
      start: new Date(2014, 8 /* Sep */, 1).getTime(),
      end: new Date(2014, 11 /* Dec */, 31).getTime(),
    });
    expect(result).toBe(true);
  });

  it("normalizes the interval if the start date is after the end date", () => {
    const result = isWithinInterval(new Date(2014, 9 /* Oct */, 31), {
      start: new Date(2014, 11 /* Dec */, 31),
      end: new Date(2014, 8 /* Sep */, 1),
    });
    expect(result).toBe(true);
  });

  it("returns false if the given date is `Invalid Date`", () => {
    const result = isWithinInterval(new Date(NaN), {
      start: new Date(2014, 8 /* Sep */, 1),
      end: new Date(2014, 11 /* Dec */, 31),
    });
    expect(!result).toBe(true);
  });

  it("returns false if the start date is `Invalid Date`", () => {
    const result = isWithinInterval(new Date(2014, 9 /* Oct */, 31), {
      start: new Date(NaN),
      end: new Date(2014, 8 /* Sep */, 1),
    });
    expect(!result).toBe(true);
  });

  it("returns false if the end date is `Invalid Date`", () => {
    const result = isWithinInterval(new Date(2014, 9 /* Oct */, 31), {
      start: new Date(2014, 11 /* Dec */, 31),
      end: new Date(NaN),
    });
    expect(!result).toBe(true);
  });

  it("properly sorts the dates", () => {
    const result = isWithinInterval(new Date(2023, 11 /* Dec */, 19), {
      start: new Date(2001, 8 /* Sep */, 1),
      end: new Date(2023, 11 /* Dec */, 20),
    });
    expect(result).toBe(true);
  });

  describe("context", () => {
    it("allows to specify the context", () => {
      const interval = {
        start: "2024-04-10T00:00:00+08:00",
        end: "2024-04-10T23:59:59+08:00",
      };
      expect(
        isWithinInterval("2024-04-09T16:00:00Z", interval, {
          in: tz("Asia/Singapore"),
        }),
      ).toBe(true);
      expect(
        isWithinInterval("2024-04-09T15:00:00Z", interval, {
          in: tz("Asia/Singapore"),
        }),
      ).toBe(false);
    });

    it("doesn't enforce argument and context to be of the same type", () => {
      function _test<DateType extends Date, ResultDate extends Date = DateType>(
        arg1: DateArg<DateType>,
        arg2: Interval<DateType>,
        options?: ContextOptions<ResultDate>,
      ) {
        isWithinInterval(arg1, arg2, { in: options?.in });
      }
    });
  });
});

import { constructFrom } from "../constructFrom/index.js";
import { toDate } from "../toDate/index.js";
import type { ContextFn, ContextOptions, DateArg } from "../types.js";

/**
 * The {@link max} function options.
 */
export interface MaxOptions<DateType extends Date = Date>
  extends ContextOptions<DateType> {}

/**
 * @name max
 * @category Common Helpers
 * @summary Return the latest of the given dates.
 *
 * @description
 * Return the latest of the given dates.
 *
 * @typeParam DateType - The `Date` type, the function operates on. Gets inferred from passed arguments. Allows to use extensions like [`UTCDate`](https://github.com/date-fns/utc).
 * @typeParam ResultDate - The result `Date` type, it is the type returned from the context function if it is passed, or inferred from the arguments.
 *
 * @param dates - The dates to compare
 *
 * @returns The latest of the dates
 *
 * @example
 * // Which of these dates is the latest?
 * const result = max([
 *   new Date(1989, 6, 10),
 *   new Date(1987, 1, 11),
 *   new Date(1995, 6, 2),
 *   new Date(1990, 0, 1)
 * ])
 * //=> Sun Jul 02 1995 00:00:00
 */
export function max<DateType extends Date, ResultDate extends Date = DateType>(
  dates: DateArg<DateType>[],
  options?: MaxOptions<ResultDate> | undefined,
): ResultDate {
  let result: ResultDate | undefined;
  let context = options?.in;

  dates.forEach((date) => {
    // Use the first date object as the context function
    if (!context && typeof date === "object")
      context = constructFrom.bind(null, date) as ContextFn<ResultDate>;

    const date_ = toDate(date, context);
    if (!result || result < date_ || isNaN(+date_)) result = date_;
  });

  return constructFrom(context, result || NaN);
}

import { constructFrom } from "../constructFrom/index.js";
import { toDate } from "../toDate/index.js";
import type { ContextFn, ContextOptions, DateArg } from "../types.js";

/**
 * The {@link min} function options.
 */
export interface MinOptions<DateType extends Date = Date>
  extends ContextOptions<DateType> {}

/**
 * @name min
 * @category Common Helpers
 * @summary Returns the earliest of the given dates.
 *
 * @description
 * Returns the earliest of the given dates.
 *
 * @typeParam DateType - The `Date` type, the function operates on. Gets inferred from passed arguments. Allows to use extensions like [`UTCDate`](https://github.com/date-fns/utc).
 * @typeParam ResultDate - The result `Date` type, it is the type returned from the context function if it is passed, or inferred from the arguments.
 *
 * @param dates - The dates to compare
 *
 * @returns The earliest of the dates
 *
 * @example
 * // Which of these dates is the earliest?
 * const result = min([
 *   new Date(1989, 6, 10),
 *   new Date(1987, 1, 11),
 *   new Date(1995, 6, 2),
 *   new Date(1990, 0, 1)
 * ])
 * //=> Wed Feb 11 1987 00:00:00
 */
export function min<DateType extends Date, ResultDate extends Date = DateType>(
  dates: Array<DateArg<DateType>>,
  options?: MinOptions<ResultDate> | undefined,
): ResultDate {
  let result: ResultDate | undefined;
  let context = options?.in;

  dates.forEach((date) => {
    // Use the first date object as the context function
    if (!context && typeof date === "object")
      context = constructFrom.bind(null, date) as ContextFn<ResultDate>;

    const date_ = toDate(date, context);
    if (!result || result > date_ || isNaN(+date_)) result = date_;
  });

  return constructFrom(context, result || NaN);
}

import { constructFrom } from "../../constructFrom/index.js";
import type { ContextFn, DateArg } from "../../types.js";

export function normalizeDates(
  context: ContextFn<Date> | undefined,
  ...dates: [DateArg<Date>, DateArg<Date>, DateArg<Date>]
): [Date, Date, Date];

export function normalizeDates(
  context: ContextFn<Date> | undefined,
  ...dates: [DateArg<Date>, DateArg<Date>]
): [Date, Date];

export function normalizeDates(
  context: ContextFn<Date> | undefined,
  ...dates: Array<DateArg<Date> & {}>
): Date[];

export function normalizeDates(
  context: ContextFn<Date> | undefined,
  ...dates: Array<DateArg<Date> & {}>
) {
  const normalize = constructFrom.bind(
    null,
    context || dates.find((date) => typeof date === "object"),
  );
  return dates.map(normalize);
}

