  it("returns the earlier endpoint for a date before the interval", () => {
    expect(clamp(new Date(2019, 11, 31), interval)).toEqual(
      new Date(2020, 0, 1),
    );
  });

  it("returns the date for a date inside the interval", () => {
    expect(clamp(new Date(2020, 0, 5), interval)).toEqual(
      new Date(2020, 0, 5),
    );
  });

  it("returns the later endpoint for a date after the interval", () => {
    expect(clamp(new Date(2020, 0, 11), interval)).toEqual(
      new Date(2020, 0, 10),
    );
  });
});

